CREATE TABLE akun (id INTEGER PRIMARY KEY, nama TEXT NOT NULL, saldo INTEGER NOT NULL CHECK (saldo >= 0));
CREATE TABLE topup (id INTEGER PRIMARY KEY, akun_id INTEGER NOT NULL, nominal INTEGER NOT NULL);
CREATE TABLE koreksi (id INTEGER PRIMARY KEY, akun_id INTEGER NOT NULL, jumlah INTEGER NOT NULL CHECK (jumlah <> 0), alasan TEXT NOT NULL CHECK (length(trim(alasan)) >= 20), admin_id INTEGER NOT NULL);
